INSERT INTO hospedajes (id, anfitrion_id, tipo, titulo, descripcion, ciudad, barrio, ubicacion, cobertura_radio_m, precio_noche, convivencia, max_mascotas, rating, num_resenas, destacado, servicios, reglas, fotos, activo) VALUES
('20000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000002', 'guarderia', 'Guardería Patitas Felices — Chapinero', 'Guardería boutique en Chapinero con grupos reducidos de juego, cámaras en vivo para que veas a tu mascota desde tu celular y reporte fotográfico diario. Contamos con áreas de descanso, patio interno y personal certificado en primeros auxilios caninos.', 'Bogotá', 'Chapinero Alto', ST_SetSRID(ST_MakePoint(-74.072, 4.711), 4326), NULL, 48000, 'compartida', 8, 4.9, 214, true, '{Juego supervisado,Cámaras en vivo 24/7,Paseos diarios,Alimentación incluida,Reporte fotográfico diario,Espacio interior climatizado}', '{Vacunas al día obligatorias,Mascotas mayores de 4 meses,Desparasitación reciente}', '{guarderia-1,guarderia-2,apto-1}', TRUE),
('20000000-0000-0000-0000-000000000002', '00000000-0000-0000-0000-000000000003', 'guarderia', 'Happy Paws Daycare — El Poblado', 'Amplio daycare en El Poblado con zona verde de 400 m², piscina para perros y entrenador en sitio. Ideal para perros sociables que disfrutan el juego con otros peludos. Ofrecemos recogida y entrega en la zona.', 'Medellín', 'El Poblado', ST_SetSRID(ST_MakePoint(-75.581, 6.244), 4326), NULL, 55000, 'compartida', 12, 4.8, 168, true, '{Zona de juegos al aire libre,Piscina para perros,Cámaras en vivo,Entrenamiento básico,Transporte opcional,Guardería nocturna}', '{Vacunas al día obligatorias,Perros sociables,Prueba de comportamiento inicial}', '{guarderia-2,guarderia-1,campestre-1}', TRUE),
('20000000-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000004', 'guarderia', 'Guardería Canina La Manada — Norte', 'Guardería con estancias individuales para mascotas que prefieren tranquilidad. Cada huésped tiene su propio espacio de descanso y rutina de paseos personalizada según su energía.', 'Cali', 'Ciudad Jardín', ST_SetSRID(ST_MakePoint(-76.532, 3.452), 4326), NULL, 40000, 'individual', 6, 4.7, 96, false, '{Cuidado individual,Cuarto propio con cama,Paseos personalizados,Alimentación según dieta,Videos diarios,Cerca eléctrica interior}', '{Vacunas al día,Indicar dieta especial,Mascotas esterilizadas preferiblemente}', '{guarderia-1,apto-2,guarderia-2}', TRUE),
('20000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000005', 'veterinaria', 'VetStay Clínica Veterinaria — Chapinero', 'Hospedaje dentro de una clínica veterinaria con supervisión médica permanente. Perfecto para mascotas con condiciones especiales, terapias o que requieren tranquilidad absoluta. Incluye chequeo diario y reporte del médico tratante.', 'Bogotá', 'Chapinero', ST_SetSRID(ST_MakePoint(-74.08, 4.649), 4326), NULL, 85000, 'individual', 4, 5.0, 187, true, '{Supervisión médica 24/7,Enfermería veterinaria,Administración de medicamentos,Hospitalización cómoda,Chequeo diario,Urgencias incluidas}', '{Historia clínica al ingreso,Vacunas al día,Mascotas con condición médica bienvenidas}', '{veterinaria-1,veterinaria-2,guarderia-1}', TRUE),
('20000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000005', 'veterinaria', 'PetCare Suite Veterinaria — Bocagrande', 'Suites de hospedaje en clínica veterinaria con aire acondicionado, ideales para el clima de Cartagena. Atención de enfermería permanente y comunicación con el dueño vía WhatsApp y videollamadas.', 'Cartagena', 'Bocagrande', ST_SetSRID(ST_MakePoint(-75.479, 10.391), 4326), NULL, 72000, 'individual', 6, 4.8, 142, false, '{Suites individuales climatizadas,Personal de enfermería,Paseos asistidos,Alimentación premium,Telemedicina para dueños,Spa post-estancia}', '{Vacunas al día,Carné de desparasitación,Apto médico para geriátricos}', '{veterinaria-2,veterinaria-1,apto-2}', TRUE),
('20000000-0000-0000-0000-000000000006', '00000000-0000-0000-0000-000000000005', 'veterinaria', 'Veterinaria Mi Mejor Amigo — Laureles', 'Clínica veterinaria con servicio de hospedaje para mascotas en recuperación o con rutinas de salud especiales. Combinamos descanso supervisado con sesiones de fisioterapia si lo requieren.', 'Medellín', 'Laureles', ST_SetSRID(ST_MakePoint(-75.581, 6.244), 4326), NULL, 90000, 'compartida', 5, 4.9, 203, true, '{Hospedaje clínico,Terapias de recuperación,Fisioterapia canina,Nutrición personalizada,Monitoreo remoto,Sala de juegos para convalecientes}', '{Remisión o historia clínica,Vacunas al día,Evaluación previa gratuita}', '{veterinaria-1,guarderia-2,veterinaria-2}', TRUE),
('20000000-0000-0000-0000-000000000007', '00000000-0000-0000-0000-000000000006', 'campestre', 'Finca Los Cerros — Hospedaje campestre', 'Finca campestre a 20 minutos de Bogotá con dos hectáreas de prado, senderos y piscina natural para perros. Tu mascota corre, explora y socializa bajo supervisión constante. Alojamiento en casas con calefacción.', 'Chía', 'Vereda Fusca', ST_SetSRID(ST_MakePoint(-74.058, 4.859), 4326), NULL, 98000, 'compartida', 10, 4.9, 156, true, '{2 hectáreas de campo,Senderos para caminatas,Piscina natural para perros,Caballeriza y zoológico de contacto,Fogata nocturna,Cámaras en zonas comunes}', '{Vacunas al día,Perros con buen comportamiento,Correa durante transporte}', '{campestre-1,campestre-2,guarderia-2}', TRUE),
('20000000-0000-0000-0000-000000000008', '00000000-0000-0000-0000-000000000006', 'campestre', 'Casa Campo Armonía — Rionegro', 'Casa campestre exclusiva en Llanogrande para estancias individuales. Cada huésped tiene jardín privado, habitación propia y atención personalizada de la anfitriona, chef de comida natural para mascotas.', 'Rionegro', 'Llanogrande', ST_SetSRID(ST_MakePoint(-75.386, 6.174), 4326), NULL, 115000, 'individual', 4, 5.0, 89, true, '{Habitación exclusiva,Jardín privado cercado,Chef de comida natural,Paseos por el bosque,Sesión de fotos incluida,Baño con productos orgánicos}', '{Reserva mínima 2 noches,Vacunas al día,Mascotas de hasta 25 kg}', '{campestre-2,campestre-1,veterinaria-1}', TRUE),
('20000000-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000007', 'campestre', 'Villa Pet Country — Villeta', 'Hacienda en clima cálido a 1.5 horas de Bogotá. Perfecta para perros que aman el agua: piscina, quebrada y mucha sombra. Grupos de juego organizados por tamaño y energía.', 'Villeta', 'Vereda La Esmeralda', ST_SetSRID(ST_MakePoint(-74.473, 5.012), 4326), NULL, 82000, 'compartida', 12, 4.7, 74, false, '{Clima cálido todo el año,Piscina para perros,Ríos y quebradas cercanas,Áreas de juego temáticas,Transporte desde Bogotá,Rappi vet cercano}', '{Vacunas al día,Aplicación de antipulgas previa,No se aceptan hembras en celo}', '{campestre-1,guarderia-2,campestre-2}', TRUE),
('20000000-0000-0000-0000-000000000010', '00000000-0000-0000-0000-000000000002', 'apartamento', 'Apartamento Pet Friendly — Galerías', 'Acogedor apartamento en Galerías donde tu mascota se queda en familia. Máximo 2 huéspedes a la vez para garantizar atención. Paseos 3 veces al día por los parques del barrio y mucho tiempo de sofá.', 'Bogotá', 'Galerías', ST_SetSRID(ST_MakePoint(-74.078, 4.665), 4326), NULL, 62000, 'individual', 2, 4.8, 131, true, '{Anfitrión en casa,Parques a 2 cuadras,Cama y juguetes incluidos,Cámaras en sala,Alimentación a la carta,Apto para gatos}', '{Vacunas al día,Mascotas menores de 15 kg,Reportar alergias o medicamentos}', '{apto-1,apto-2,guarderia-1}', TRUE),
('20000000-0000-0000-0000-000000000011', '00000000-0000-0000-0000-000000000003', 'apartamento', 'Suite Urbana — Laureles', 'Apartamento en Laureles con terraza propia donde las mascotas juegan y toman sol. Paseos diarios por la Unidad Deportiva. Máximo 3 huéspedes para mantener un ambiente tranquilo.', 'Medellín', 'Laureles', ST_SetSRID(ST_MakePoint(-75.581, 6.244), 4326), NULL, 68000, 'compartida', 3, 4.6, 88, false, '{Terraza con grama sintética,Ruta de paseos diaria,Snacks saludables,Reporte por video,Perros y gatos,Primeros auxilios certificado}', '{Vacunas al día,Comportamiento verificado,Avisar con 48 h de anticipación}', '{apto-2,apto-1,campestre-2}', TRUE),
('20000000-0000-0000-0000-000000000012', '00000000-0000-0000-0000-000000000004', 'apartamento', 'Apartamento Céntrico — Cabecera', 'Hospedaje individual en el corazón de Bucaramanga. Una sola mascota a la vez: atención total, comida casera y paseos mañana y tarde. Ideal para perros ansiosos o que extrañan mucho a su familia.', 'Bucaramanga', 'Cabecera del Llano', ST_SetSRID(ST_MakePoint(-73.123, 7.119), 4326), NULL, 45000, 'individual', 1, 4.9, 67, false, '{Solo un huésped a la vez,Anfitriona amante de perros,Parque a 5 minutos,Comida casera incluida,Videos diarios,Cuidado 24/7}', '{Vacunas al día,Mascotas de cualquier tamaño,Reserva mínima 1 noche}', '{apto-1,guarderia-1,apto-2}', TRUE),
('20000000-0000-0000-0000-000000000013', '00000000-0000-0000-0000-000000000002', 'domicilio', 'Cuidadora a domicilio — Chapinero', 'Carolina se desplaza hasta tu residencia para cuidar a tu mascota en su propio entorno: sin cambios de rutina, sin estrés de traslado y con todo el cariño de siempre. Visitas 2 veces al día o estancia completa, con reporte diario y comunicación constante.', 'Bogotá', 'Chapinero Alto', ST_SetSRID(ST_MakePoint(-74.067, 4.695), 4326), 12000, 70000, 'individual', 3, 4.9, 58, true, '{La cuidadora va a tu casa,Paseos diarios por tu barrio,Reporte con fotos y video,Cuidado de plantas y correspondencia,Rutina y alimentación exactas,Seguro de responsabilidad}', '{Mascotas con vacunas al día,Zona Chapinero y alrededores,Entrevista previa gratuita}', '{apto-1,apto-2,guarderia-1}', TRUE),
('20000000-0000-0000-0000-000000000014', '00000000-0000-0000-0000-000000000003', 'domicilio', 'Pet sitter en tu casa — El Poblado', 'Andrés se queda en tu casa mientras viajas: tu mascota mantiene sus horarios, sus paseos y su cama. Ideal para perros que se estresan con lugares nuevos. Incluye cuidados de la casa y reporte diario.', 'Medellín', 'El Poblado', ST_SetSRID(ST_MakePoint(-75.575, 6.215), 4326), 12000, 75000, 'individual', 3, 4.8, 47, true, '{Estancia completa en tu hogar,Paseos 3 veces al día,Fotos y videos diarios,Rutina personalizada,Cuidado nocturno,Comunicación constante}', '{Vacunas al día,Mascotas de hasta 30 kg,Coordinación previa de rutinas}', '{apto-2,apto-1,campestre-2}', TRUE),
('20000000-0000-0000-0000-000000000015', '00000000-0000-0000-0000-000000000004', 'domicilio', 'Cuidador a domicilio — Ciudad Jardín', 'Valentina cuida a tu mascota en tu propia casa con visitas programadas o estancia parcial. Perfecto para gatos y perros que prefieren no salir de su territorio. Reporte con foto en cada visita.', 'Cali', 'Ciudad Jardín', ST_SetSRID(ST_MakePoint(-76.52, 3.417), 4326), 12000, 60000, 'individual', 2, 4.7, 33, false, '{Visitas 2 veces al día,Paseos mañana y tarde,Alimentación según dieta,Reporte por WhatsApp,Limpieza de areneros (gatos),Flexibilidad de horarios}', '{Vacunas al día,Zona Ciudad Jardín y aledaños,Indicar dieta y medicamentos}', '{apto-1,guarderia-1,apto-2}', TRUE),
('20000000-0000-0000-0000-000000000016', '00000000-0000-0000-0000-000000000007', 'domicilio', 'Cuidadora a domicilio — Usaquén', 'Jorge se desplaza hasta Usaquén para cuidar a tu mascota en casa: visitas dos veces al día o estancia completa. Amplia experiencia con mascotas senior y administración de medicamentos.', 'Bogotá', 'Usaquén', ST_SetSRID(ST_MakePoint(-74.031, 4.694), 4326), 12000, 68000, 'individual', 2, 4.8, 41, true, '{Visitas mañana y tarde,Paseos en el parque El Country,Reporte fotográfico diario,Alimentación y medicamentos,Experiencia con mascotas senior,Llaves con seguro}', '{Vacunas al día,Zona Usaquén y alrededores,Entrevista previa gratuita}', '{apto-2,apto-1,guarderia-1}', TRUE),
('20000000-0000-0000-0000-000000000017', '00000000-0000-0000-0000-000000000007', 'domicilio', 'Pet sitter — Alto Prado', 'Cuidador en el norte de Barranquilla: tu mascota se queda en casa con aire acondicionado, paseos a horas frescas del día y reporte constante para ti.', 'Barranquilla', 'Alto Prado', ST_SetSRID(ST_MakePoint(-74.795, 10.995), 4326), 12000, 65000, 'individual', 3, 4.8, 39, false, '{Estancia en tu hogar,Paseos a horas frescas,Climatización y agua constante,Reporte por WhatsApp,Cuidado de gatos y perros,Flexibilidad de horarios}', '{Vacunas al día,Zona norte de Barranquilla,Indicar rutinas de alimentación}', '{apto-1,apto-2,campestre-1}', TRUE),
('20000000-0000-0000-0000-000000000018', '00000000-0000-0000-0000-000000000002', 'domicilio', 'Cuidado en tu casa — Teusaquillo', 'Cuidado a domicilio en Teusaquillo con visitas múltiples al día, cerca a parques y con la tranquilidad de que tu mascota nunca sale de casa.', 'Bogotá', 'Teusaquillo', ST_SetSRID(ST_MakePoint(-74.084, 4.657), 4326), 12000, 62000, 'individual', 3, 4.9, 52, false, '{Visitas 2-3 veces al día,Paseos cerca a la Av. 26,Cámara y reporte diario,Alimentación según dieta,Cuidado de plantas,Disponible fines de semana}', '{Vacunas al día,Zona Teusaquillo y alrededores,Entrevista previa}', '{apto-1,guarderia-1,apto-2}', TRUE);
